insert into public.inspection_responses (id, inspection_id, template_item_id, condition_rating, detail, applicable)
select v.id::uuid, '9afae910-cf7b-5997-9dcd-042d9a195bee'::uuid, iti.id, v.cond, v.detail::jsonb, true
from (values
    ('898571e0-fce7-512b-8602-15e21bf6032d', '1', null, '{"Property address": "CNR UTRECH AND MASON STREET VRYHEID", "Practical completion": "Building was revamped and opened on 22 November 2023", "Further expansions: (if yes please provide dates)": "N/A", "Total GLA m\u00b2": "16811", "Current vacancy m\u00b2": "0", "Parking bays": "106", "Basement": "N/A", "Open": "106", "Covered parking": "Taxi Rank", "Shaded parking": "0", "Motorbike": "0", "Moms and tods": "0", "Disabled": "6", "Taxi bays": "350", "Number of tenants": "46, 4 x ATM, Astron, Cashbuild", "List of anchor tenants": "Shoprite, Boxer PEP, Ackermans", "Quantity national tenants": "42", "Quantity private shops": "4"}'),
    ('05c42f82-0d37-56a2-94bc-7a703d6c01df', '4.1', 'good', '{"Type of system installed": "Zion 3 Fire Panel installed for smoke and fire detection. System is linked to the fire pump, alarm will sound when the fire pump starts.", "Make & model of panels": "Zion ZP3", "Brief description of how the system operates": "The main panel is connected to smoke detectors that are grouped in to zones to pin point detection. The panel is situated in the control room where security can notify centre management of an alarm activation.", "Service frequency": "Bi Annually", "Last date serviced": "08/2025", "Next service due": "02/2026", "Service fee cost": "R12776.04", "Service provider / contractor / installed by": "Multi-Net Systems", "Number of detectors": "58", "Type of detectors (specify how many you have of each type of detector e.g., 10 Smoke, 10 heat etc.)": "Ceiling optical detectors - 31\nCeiling void detectors - 18\nHeat detectors - 3\nManual Call points - 6", "As built plan available": "Yes", "Cost Recovery: Tenant specific / part of ops cost": "Part of OPS cost", "Current status: (Good, Fair, Poor)": "Good", "General comment": "2 faults on system Z001 Shop 2-5 and 003 Supply", "Inspection checklist: Daily/weekly/monthly": "Weekly", "N/A": "N/A"}'),
    ('88961d54-e68d-5f5b-b886-b0ce21852836', '4.2', 'good', '{"Type of system installed": "Fusible Link", "Brief description of how the system operates": "Fusible Link : Wen there is a fire the heat will trigger the fuse causing the closed louvers to open.\n\nMechanical Extraction : Vents are connected to the smoke detectors. As soon as the detector detects smoke the louvers will open and fans will extract the smoke.", "Make & model": "Tenants - Curvent\nFusible Link\nFire - X Type 1620G EN", "Service frequency": "Annually", "Last date serviced": "08/2025", "Next service due": "08/2026", "Service fee cost": "17750", "Service provider / contractor / installed by": "Curvent", "If vents are installed, specify number of vents per tenant": "Shoprite - 10\nAckerman''s - 5\nClicks - 6\nJet - 6\nBoxer - 10 - New", "If mechanical extraction units are installed, specify number of units per tenant": "Mall - 4", "As built plan available": "Yes", "Cost Recovery: Tenant specific / part of ops cost": "OPS and Tenant Cost", "Current status: (Good, Fair, Poor)": "Good", "General comment": "None", "Inspection checklist: Daily/Weekly/Monthly": "Monthly"}'),
    ('ae18d6a0-d2bb-503f-9031-e41fbfd99f1e', '4.3', 'good', '{"Give a brief description of how the system operates": "Fire extinguisher: it releases a cloud of carbon dioxide that smothers the fire.\n\nHose Reel: You pull the hose from the reel, turn the main valve to supply water, then use the nozzle to spray water at the base of the flames.\n\nFire hydrant: A system of pipe work connected directly to the water supply main to provide water to every hydrant outlet and is intended to provide water for the firemen to fight a fire.", "Location plan available": "Yes", "Service frequency": "Yearly", "Last date serviced": "01/2026 missed in Dec/25  Inverter extinguishers service in August", "Next service due": "01/2027", "Service fee cost": "R6339.78", "Service provider / contractor / installed by": "Baytech Fire CC", "Number of fire hose reels in building": "12", "Number and type of fire extinguishers on the premises": "29 - 4,5Kg DCP/STP x 18 - 9Kg DCP/STP x 9 - 5Kg Co2 X 5 - Lith 2Kg x 2", "Number and type of fire extinguishers for tenants": "112", "Last service certificate obtained": "Yes", "Number of hydrants on the premises": "13", "Cost Recovery: Tenant specific / part of ops cost": "Tanat Specific and Part of ops cost.", "Current status: (Good, Fair, Poor)": "Good", "General comments": "None", "Inspection checklist: Daily/weekly/monthly": "Monthly"}'),
    ('6bc1836a-f292-5da6-9990-be2e19ae57fa', '4.4', 'good', '{"Give a brief description of how the system operates": "By using heat-sensitive triggers in individual sprinkler heads will automatically release water directly onto a fire, controlling or extinguishing it quickly before it spreads, with only the specific zone activating. Diesel engine to add required pressure.", "What type of sprinkler pump is on premises?": "Deveron 150KW Diesel Pump", "Diesel, Electrical, Jockey pump": "Granados Jockey Pumps", "Size and specs of diesel or electrical pump": "Deveson 150KW Pump", "Size and specs of jockey pump": "3 KW", "If a backup water tank is present, indicate capacity": "580KL", "As built plan available": "Yes", "Diesel day tank capacity": "80L", "Diesel bulk tank capacity": "N/A", "Service frequency": "Every 3 years", "Last date serviced": "08/2023", "Next service due": "08/2026", "Service fee cost": "1st under warranty cost to be obtained", "Service provider / contractor / installed by": "Secure Fire", "Number of ICV valves on the premises": "3", "Cost Recovery: Tenant specific / part of ops cost": "Tenant and OPS Cost", "Current status: (Good, Fair, Poor)": "Good", "General comments": "None", "Inspection checklist: Daily/weekly/monthly": "Weekly"}'),
    ('4e38a680-9c47-59a7-89cc-891a3aea4f05', '4.5', 'fair', '{"Installation date": "2022", "Service provider / contractor / installed by": "Secure fire / baytek / Zero tolerance", "Cost Recovery: Tenant specific / part of ops cost": "Tenant and Part of OPS Cost", "Current status: (Good, Fair, Poor)": "Fair", "General comment": "None", "Inspection checklist: Daily/weekly/monthly": "Weekly"}'),
    ('cc96dd77-603d-5b03-9672-6eebc4871e2c', '5.1', 'good', '{"Brief description of system installed": "System covering common area, parking and roof", "Type of cameras installed": "Hikvision Camera System", "As built plan available": "No", "Installation date": "2023.", "Upgrade date": "5 - 10 Years", "Quantity and type of cameras": "86", "Inspection checklist: Daily/weekly/monthly": "Daily", "Cost Recovery: Tenant specific / part of ops cost": "Part of OPS cost", "Current status: (Good, Fair, Poor)": "Good", "General comment": "None"}'),
    ('f32bbade-9022-5d56-879c-d2d7807f675c', '5.2', null, '{"Brief description of system installed": "Security has Panic response to K9 Security to provide armed response. System for Mall to be installed.", "Quantity of remotes on hand": "3", "As built plan available": "N/A", "Installation date": "2026-11-23", "Upgrade date": "To be determined", "Frequency of test performed: Weekly/Daily": "Weekly", "Armed reaction services or control room monitored": "Armed reaction", "Please indicate where this is captured": "Security", "Cost Recovery: Tenant specific / part of ops cost": "SLA - Part of OPS Cost"}'),
    ('6d0a71f0-558d-5e37-bb4b-ee3c01732985', '5.3', null, '{"Explain how the evacuation procedure works": "Procedure document shared with all tenants on safety measures during an emergency and how to safely evacuate.", "Where is the evacuation process documented?": "In our evacuation procedure distributed to tenants. CM - Wall and walkway walls", "How often is the evacuation process tested?": "Bi Annually", "Last date that evacuation procedure was tested": "17/12/2025", "Next scheduled dates of evacuation procedure testing": "17/06/2026", "Amount of static assembly points": "5", "Amount of manual assembly points": "N/A", "Were any issues identified with the last evacuation testing drill? Please elaborate on how this was resolved": "Fire Alarm not loud enough", "N/A": "N/A"}'),
    ('48c4ab68-b99a-5b9b-b727-174a749f8972', '5.4', null, '{"Type of equipment: Provide a list": "Electric fence", "Brief description of system installed": "N/A", "Quantity of equipment": "N/A", "Current status: (Good, Fair, Poor)": "N/A", "General comment": "N/A", "Repair cost": "N/A", "Service provider / contractor / installed by": "N/A", "Inspection checklist: Daily/weekly/monthly": "N/A"}'),
    ('4f88c157-afec-5ad7-ae34-8f09b924d9fd', '6.1', null, '{"High tension room supply": "3 transformers for site 1 municipal", "Switch gear": "No", "Voltage": "11KV / 400", "As built plan available": "Yes", "Who is responsible for the HT room equipment?": "OPS Cost", "Number of transformers on site": "3", "Type of transformers": "Dyn 11, 630KVA,11KV /400", "Service frequency": "Annually", "Last date serviced": "2025-02-01", "Next service due": "2026-02-01", "Service fee cost": "7600", "Service provider / contractor / installed by": "Kambula", "Cost Recovery: Tenant specific / part of ops cost": "OPS Cost", "Are all COCs in place": "Yes", "Are infrared scans performed": "Yes", "Frequency of scans: Bi-annually / annually etc.": "Annually", "Latest scan performed": "2025-02-01", "Next scan to be performed": "2026-02-01", "Who performs the scan, specify contractor?": "Kambula", "Last scanned report available and were all issues resolved": "Yes", "Cost of a scan": "7600", "List of DBs available": "Yes"}'),
    ('049c155a-374c-5b7a-87ee-8296dfa96f48', '6.3', null, '{"Is there power factor correction equipment installed?": "N/A", "If yes please elaborate": "N/A", "As built plan available": "N/A", "Current power factor reading": "N/A", "Service frequency": "N/A", "Last date serviced": "N/A", "Next service due": "N/A", "Service fee cost": "N/A", "Service provider / contractor / installed by": "N/A", "Cost Recovery: Tenant specific / part of ops cost": "N/A"}'),
    ('8e598b7f-04a4-5447-8f42-a4aa56a5d7c0', '6.4', 'good', '{"Give a brief description of how generator operates": "If the power supply from council switches off, our generator has a change over switch. This then automatically starts the generator. All tenants have emergency dB boards in their premises. If they choose to connect to our genset we will be able to turn them on by switch of a key", "As built plan available": "Yes", "Generator running hours: Date/hours": "Gen 1 = 607h10m Gen 2 = 619h 41m", "Size generator": "2 X 350KVA generators feeding line tenants\nAnchor tenants have there own generators", "Specs of generator": "Gen 1 = SDEC 6ETAA Serial: E9234001934 Gen 2 = SDEC 6ETAA Serial: E9236003761", "Life span expectancy of generator": "15 - 20 Years", "Installation date": "2023-11-01", "Day tank capacity": "N/A", "Bulk tank capacity": "1000L", "Service frequency": "250 hours or Annually", "Last date serviced": "22/04/2025", "Next service due": "22/04/2026", "Service fee cost": "R 10 655,00 per unit = 21310,00", "Service provider / contractor / installed by": "GDS", "Cost Recovery: Tenant specific / part of ops cost": "OPS Cost and tenant", "Current status: (Good, Fair, Poor)": "Good", "General comment": "None", "Inspection checklist: Daily/weekly/monthly": "Weekly"}'),
    ('17107f68-aca4-5b3f-8ab9-a485f7894864', '6.5', 'good', '{"As built plan available": "Yes", "Size of solar plant": "22 833,59m2 7X 125KW inverters 1925 Panels", "Installation date": "2023.", "Amount and type of solar panels": "1925 panels 555W 2,564m2", "Amount and type of invertors": "7 x 125KW Sungrow", "kWh production of plant": "5300 KWh Daily", "Is an SLA in place?": "Yes", "Performance/production guarantee (is calculated over 12 months): (Yes/No)": "Yes", "Cleaning service frequency": "Every 3 Months", "Plant performance reporting frequency": "Monthly", "Last date serviced": "As per SLA", "Next service due": "As per SLA", "Service provider / contractor / installed by": "Terra firma", "Cost Recovery: Tenant specific / part of ops cost": "Part of OPS Cost", "Current status: (Good, Fair, Poor)": "Good", "General comments": "None", "Inspection checklist: Daily/weekly/monthly": "Weekly"}'),
    ('9072a256-701b-595f-af26-ed8ddad3c2a6', '6.6', null, '{"Type of meters installed": "Kamstrup", "Main connection with size of connection": "80mm", "What tariff the mall gets invoiced": "Industrial kVA", "How is sanitation billed per point or per %?": "per m2", "Gas operations \u2013 how does it work": "Tenants are billed as per usage photos sent to PEC", "As built plan available": "Yes", "Is an SLA in place?": "Yes", "Prepaid system installed": "N/A", "How many tenants are on prepaid?": "N/A", "Latest technical audit report (done by utility company)": "2024"}'),
    ('14125fc3-d7ae-5635-9539-705810427479', '7', 'good', '{"Give a brief description of how the system works": "Once you set the temperature on the control panel to the desired temperature it will trigger the condenser fan and compressor to turn on. The compressor will start pumping the refrigerant liquid through the compressor into the condenser coils in the outdoor units. This will take the refrigerant from the inside temperature and will be released outside. The refrigerant leaves the condenser as a high pressure liquid then flows to the metering device, and goes through an expansion valve it will then pass through a expansion coil which will change it from a liquid to a vapour. Which reduces the temperature as per the control panels temperature. This will then disperse the cold air into the premises", "As built plan available": "No", "Type of system: (Chiller system, VRV system)": "Multiple - MWS, Ducted and package", "Number of units": "To be counted", "Installation date": "2022", "Service frequency": "Quarterly", "Last monthly service date": "Minor Sep", "Next monthly service date": "Minor Jan", "Last major service date": "13 Dec Handover", "Next major service date": "2026-12-01", "Service fee cost": "3800", "Service provider / contractor / installed by": "Total Comfort", "Is an SLA in place?": "Yes", "Cost Recovery: Tenant specific / part of ops cost": "Part of OPS Cost. Tenants service their own units", "Breakdown of equipment": "We have ducted plants, cassette units, midwall splits and evap coolers", "Current status: (Good, Fair, Poor)": "Good", "General comment": "None", "Inspection checklist: Daily/weekly/monthly": "Weekly"}'),
    ('13336a73-985c-5999-8b5b-866fdf9ea57a', '8', null, '{"Give a brief description of how extraction system operates": "Cooker hood over the stoves extract the hot air allowing heat to escape the building.", "As built plan available": "No", "Type of equipment": "Extraction canopies and air extraction fans", "Number of units": "8 Canopy units", "Installation date": "2023.", "Service frequency": "Bi Annually", "Last date serviced": "Dec 2024 total comfort under warranty", "Next service due": "One to be done in Jan", "Service fee cost": "Tenant cost", "Service provider / contractor / installed by": "Cool Craft", "Cost Recovery: Tenant specific / part of ops cost": "Tenant Cost", "Inspection checklist: Daily/weekly/monthly": "Monthly"}'),
    ('6f9d42d2-546b-5ca9-ac23-2de2c71e3d60', '9.1', 'good', '{"Type of lights installed": "LED lights, LED downlights and LED strip lights.", "Are motion sensors installed": "No", "Day night switch or timer": "Timer", "Service provider / contractor / installed by": "Kambula", "Inspection checklist: Daily/weekly/monthly": "Daily", "Cost Recovery: Tenant specific / part of ops cost": "OPS Cost", "Current status: (Good, Fair, Poor)": "Good", "General comment": "None"}'),
