    ('a345ce72-4876-50e9-819e-dc758fc91754', '10.1', null, '{"Describe the structural condition of the internal walls": "Plastered Brick Wall, Concrete columns, Tenants Drywall", "Describe the condition of the paint / marmoran on the internal walls": "Minor painting to be done", "When last were the walls painted": "1905-07-15", "Type and colour code of paint used": "Plascon,Rhine stone.", "Is there a warranty on the paint? What is the warranty term?": "2023.", "When will the next paint job be budgeted for?": "2027.", "Inspection checklist: Daily/weekly/monthly": "Daily"}'),
